import { canonicalSet, labelFor } from "./ontology";
import { mentorDirection, studentDirection } from "./compatibility";
import type { MentorProfile, Milestone, StudentProfile } from "./types";

/**
 * Template-based first-meeting preparation and development milestones.
 * Deterministic: built only from the student's reviewed fields and the mentor's profile.
 * This is NOT generated by an AI model.
 */
export const MILESTONE_LABEL = "Template-based suggestions from reviewed profile fields — not AI-generated.";

export function firstMeetingPrep(s: StudentProfile, m: MentorProfile): string[] {
  const mf = m.name.split(" ")[0];
  const prep: string[] = [];
  if (s.careerGoals.trim()) prep.push(`Open with your goal in two sentences: “${s.careerGoals.trim()}”`);
  if (m.trajectory.length >= 2) {
    const a = m.trajectory[0];
    const b = m.trajectory[m.trajectory.length - 1];
    prep.push(`Ask ${mf} what changed between working as ${article(a.role)} and becoming ${article(b.role)}.`);
  }
  const shared = [...studentDirection(s)].filter((x) => mentorDirection(m).has(x));
  if (shared.length) prep.push(`Ask what a strong first year in ${labelFor(shared[0]).toLowerCase()} looks like, and what ${mf} would do differently.`);
  const gap = expertiseGap(s, m);
  if (gap) prep.push(`Bring one specific question about ${gap.toLowerCase()} — it’s in ${mf}’s expertise but not yet in your skills.`);
  prep.push(`Agree on how you’ll stay in touch: ${mf}’s preference is “${truncate(m.mentoringPreferences, 110)}”`);
  return prep;
}

export function generateMilestones(s: StudentProfile, m: MentorProfile, idPrefix: string): Milestone[] {
  const mf = m.name.split(" ")[0];
  const role = s.targetRoles[0] ?? "your target role";
  const industry = s.industries[0] ?? m.industries[0] ?? "your field";
  const gap = expertiseGap(s, m);
  const items: Omit<Milestone, "id" | "done">[] = [
    {
      title: `Write a one-page brief on the ${role.toLowerCase()} role`,
      detail: `What the work involves day to day, three teams you’d want to join, and what you still need to learn. Share it with ${mf} before your second conversation.`,
      basis: `Target role: ${role}`,
    },
    {
      title: `Rework three resume bullets toward ${role.toLowerCase()}`,
      detail: `Rewrite your strongest experiences around outcomes that matter for ${role.toLowerCase()} work, then ask ${mf} for one round of feedback.`,
      basis: `Target role: ${role}`,
    },
    gap
      ? {
          title: `Build practice in ${gap.toLowerCase()}`,
          detail: `Pick one small project or exercise that demonstrates ${gap.toLowerCase()}, and walk ${mf} through it.`,
          basis: `${mf}’s expertise not yet in your skills: ${gap}`,
        }
      : {
          title: `Deepen one existing strength`,
          detail: `Choose the skill you and ${mf} share and set a concrete next step for it.`,
          basis: `Shared skills`,
        },
    {
      title: `Ask for one introduction in ${industry.toLowerCase()}`,
      detail: `With ${mf}’s agreement, request a conversation with one person working in ${industry.toLowerCase()}. Prepare three questions first.`,
      basis: `Industry: ${industry}`,
    },
  ];
  return items.map((x, i) => ({ ...x, id: `${idPrefix}-ms-${i + 1}`, done: false }));
}

function expertiseGap(s: StudentProfile, m: MentorProfile): string | null {
  const have = canonicalSet([...s.skills]);
  const gap = m.expertise.find((e) => {
    const [c] = [...canonicalSet([e])];
    return c && !have.has(c);
  });
  return gap ?? null;
}

function article(role: string) {
  const r = role.toLowerCase();
  return /^[aeiou]/.test(r) ? `an ${r}` : `a ${r}`;
}

function truncate(s: string, n: number) {
  return s.length > n ? `${s.slice(0, n - 1).trimEnd()}…` : s;
}
